    Bug 1933402 - Fix memory leak in nsMsgDBFolder::ClearFlag. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D230221

diff --git a/mailnews/base/src/nsMsgDBFolder.cpp b/mailnews/base/src/nsMsgDBFolder.cpp
index cd30bf7db2a..b6cd4f24710 100644
--- a/mailnews/base/src/nsMsgDBFolder.cpp
+++ b/mailnews/base/src/nsMsgDBFolder.cpp
@@ -3901,28 +3901,39 @@ NS_IMETHODIMP nsMsgDBFolder::SetFlag(uint32_t flag) {
   bool flagSet;
   nsresult rv;

-  if (NS_FAILED(rv = GetFlag(flag, &flagSet))) return rv;
-
+  if (NS_FAILED(rv = GetFlag(flag, &flagSet))) {
+    return rv;
+  }
   if (!flagSet) {
     mFlags |= flag;
     OnFlagChange(flag);
   }
-  if (!dbWasOpen && mDatabase) SetMsgDatabase(nullptr);
+  if (!dbWasOpen && mDatabase) {
+    SetMsgDatabase(nullptr);
+  }

   return NS_OK;
 }

 NS_IMETHODIMP nsMsgDBFolder::ClearFlag(uint32_t flag) {
+  // If calling this function causes us to open the db (i.e., it was not
+  // open before), we're going to close the db before returning.
+  bool dbWasOpen = mDatabase != nullptr;
+
   // OnFlagChange can be expensive, so don't call it if we don't need to
   bool flagSet;
   nsresult rv;

-  if (NS_FAILED(rv = GetFlag(flag, &flagSet))) return rv;
-
+  if (NS_FAILED(rv = GetFlag(flag, &flagSet))) {
+    return rv;
+  }
   if (flagSet) {
     mFlags &= ~flag;
     OnFlagChange(flag);
   }
+  if (!dbWasOpen && mDatabase) {
+    SetMsgDatabase(nullptr);
+  }

   return NS_OK;
 }
